            initial={instant ? { opacity: 0 } : { opacity: 0, scale: 0.9, y: 8 }}
            animate={instant ? { opacity: 1 } : { opacity: 1, scale: 1, y: 0 }}
            exit={instant ? { opacity: 0 } : { opacity: 0, scale: 0.94 }}
            transition={instant ?? springs.snappy}
            onMouseMove={track}
          >
