                  key={a.label}
                  className={`gm-sheet-action${a.danger ? " gm-danger" : ""}`}
                  initial={instant ? false : { opacity: 0, y: 12 }}
                  animate={{ opacity: 1, y: 0 }}
                  transition={{ ...(instant ?? springs.soft), delay: instant ? 0 : 0.1 + i * 0.05 }}
                  onClick={() => setOpen(false)}
