                    >
                      <button className="gm-acc-row">{r}<ChevronRight size={13} className="gm-dim" /></button>
                    </motion.li>
                  ))}
                </ul>
              </motion.div>
            )}
          </AnimatePresence>
        </div>
      ))}
    </div>
  );
}

