        {pos && (<motion.div ref={panelRef} role="menu" className="gm-panel gm-spot-panel" style={{ left: pos.x, top: pos.y, transformOrigin: "top left" }} initial={instant ? { opacity: 0 } : { opacity: 0, scale: 0.9, y: 8 }} animate={instant ? { opacity: 1 } : { opacity: 1, scale: 1, y: 0 }} exit={instant ? { opacity: 0 } : { opacity: 0, scale: 0.94 }} transition={instant ?? springs.snappy} onMouseMove={track}>
            {spotItems.map((item, i) => (<motion.button key={item.n} role="menuitem" className={`gm-item gm-spot-item${item.label.includes("Delete") ? " gm-danger" : ""}`} initial={instant ? false : { opacity: 0, y: 6 }} animate={{ opacity: 1, y: 0 }} transition={{ ...(instant ?? springs.soft), delay: instant ? 0 : 0.05 + i * 0.035 }} onClick={() => setPos(null)}>
                <span className="gm-spot-num">{item.n}</span>
                <span className="gm-item-icon">{item.icon}</span>
                <span className="gm-item-label">{item.label}</span>
              </motion.button>))}
          </motion.div>)}
      </AnimatePresence>
    </div>);
}
